-- Die Startseite im Editor (ueberarbeitet)
--
-- Der erste Anlauf sass beim Zeitstrahl, wich aber beim Rest ab: Das Band mit
-- den Eckdaten war zu dunkel (bg-muted statt bg-muted/30), die Abschnitte
-- hatten weniger Luft als das Original (py-12 statt py-16), und der
-- Terminabschnitt war eine Neufassung statt der bestehenden Darstellung -
-- andere Karten, kein Datumsbereich, keine Uhrzeit.
--
-- Ausserdem brauchte es getrennte Abstaende oben und unten: Text, Bild und
-- Link stehen im Original dicht untereinander in einem Abschnitt, der als
-- Ganzes viel Luft hat. Mit einem Wert fuer beide Seiten wird entweder der
-- Abschnitt zu eng oder die Teile darin zu weit auseinander.

INSERT INTO public.site_pages (slug, title, content, draft_content, seo_description, is_published, published_at)
VALUES (
  'startseite-neu',
  'Startseite',
  '{"content": [{"type": "Willkommen", "props": {"id": "Willkommen-5fc2034d", "bildSchluessel": "hero-startseite", "ueberschrift": "Nassauische Geschichte lebendig erleben", "text": "<p>Seit 2011 beschäftigen wir uns als Wiesbadener Verein mit der Geschichte des Nassauer Landes – vom Spätmittelalter bis zum Ersten Weltkrieg.</p><p>In unseren Darstellungen versuchen wir, diese Zeit möglichst authentisch erfahrbar zu machen und den Menschen von damals wieder ein Gesicht zu geben – auf Grundlage historischer Quellen und sorgfältiger Recherche.</p>", "knopf1": "Veranstaltungsanfrage stellen", "ziel1": "/fuer-veranstalter", "knopf2": "Unser Verein", "ziel2": "/verein", "hoehe": "mittel"}}, {"type": "Eckdaten", "props": {"id": "Eckdaten-2ef8f7b7", "abstandOben": "klein", "abstandUnten": "klein", "eintraege": [{"symbol": "kalender", "text": "Seit", "hervorgehoben": "2011 aktiv"}, {"symbol": "leute", "text": "", "hervorgehoben": "3 Epochen dargestellt"}, {"symbol": "ort", "text": "Fokus", "hervorgehoben": "Region Wiesbaden"}]}}, {"type": "Zeitstrahl", "props": {"id": "Zeitstrahl-51d8951d", "ueberschrift": "Unsere Darstellungen", "hintergrund": "karte", "abstandOben": "weit", "abstandUnten": "weit", "punkte": [{"titel": "Spätmittelalter", "jahre": "1290–1310", "untertitel": "Grafschaft Nassau", "bildSchluessel": "epochenkarte-mittelalter", "ziel": "/epochen/mittelalter"}, {"titel": "Napoleonik", "jahre": "1815", "untertitel": "Herzogtum Nassau", "bildSchluessel": "epochenkarte-napoleonik", "ziel": "/epochen/1815"}, {"titel": "Erster Weltkrieg", "jahre": "1916/17", "untertitel": "Provinz Hessen-Nassau", "bildSchluessel": "epochenkarte-wk1", "ziel": "/epochen/wk1"}]}}, {"type": "Textabschnitt", "props": {"id": "Textabschnitt-dd7b76e5", "breite": "schmal", "ausrichtung": "mitte", "abstandOben": "weit", "abstandUnten": "keiner", "textfarbe": "standard", "hintergrund": "keine", "inhalt": "<h2>Wer wir sind</h2><p>Diu lebendec Histôrje – mittelhochdeutsch für „die lebendige Geschichte“ – ist ein gemeinnütziger Verein aus Wiesbaden. Seit 2011 beschäftigen wir uns mit der Geschichte des Nassauer Landes vom Spätmittelalter bis zum Ersten Weltkrieg.</p><p>In unseren Darstellungen versuchen wir, diese Zeit möglichst authentisch erfahrbar zu machen – auf Grundlage historischer Quellen, archäologischer Funde und eigener Rekonstruktionen. Besonders interessiert uns dabei der Alltag gewöhnlicher Menschen und nicht nur das Leben von Herrschern oder Militärs.</p><p>Unsere Arbeit zeigen wir vor allem auf Veranstaltungen von Museen und historischen Einrichtungen, wo wir Geschichte durch Gespräche, Vorführungen und Displayarbeit für Besucher greifbar machen.</p>"}}, {"type": "Einzelbild", "props": {"id": "Einzelbild-1f090bcb", "breite": "schmal", "abstandOben": "klein", "abstandUnten": "keiner", "bildSchluessel": "gruppenfoto-startseite", "bildunterschrift": ""}}, {"type": "Knopf", "props": {"id": "Knopf-1d6013b4", "breite": "schmal", "abstandOben": "eng", "abstandUnten": "weit", "beschriftung": "Mehr über unseren Verein →", "ziel": "/verein", "zielFrei": "", "art": "schlicht", "ausrichtung": "mitte"}}, {"type": "Termine", "props": {"id": "Termine-d6d9fc2c", "breite": "schmal", "abstandOben": "weit", "abstandUnten": "weit", "ueberschrift": "Nächste Termine", "unterzeile": "Hier findet ihr unsere öffentlichen Auftritte und Veranstaltungen.", "anzahl": 10}}, {"type": "Aktionskaesten", "props": {"id": "Aktionskaesten-f5d6ade9", "hintergrund": "karte", "abstandOben": "weit", "abstandUnten": "weit", "kaesten": [{"titel": "Für Veranstalter", "text": "Sie planen eine Veranstaltung mit historischem Bildungsanspruch? Wir freuen uns über Ihre Anfrage.", "knopf": "Anfrage stellen", "ziel": "/fuer-veranstalter", "betont": true}, {"titel": "Für Interessierte", "text": "Geschichte begeistert Sie – und vielleicht möchten Sie mehr als nur zuschauen?", "knopf": "Mehr über uns erfahren", "ziel": "/verein", "betont": false}]}}], "root": {"props": {"title": "Startseite"}}}'::jsonb,
